[
  {
    "id": "no_cart_in_single_file_shelf_aisle",
    "text": "A shopper must not take a cart into a single-file aisle flanked by shelves on both sides.",
    "abstraction": {
      "state_properties": {
        "single_file_shelf_aisle": {
          "or": [
            {
              "and": [
                "shelfE",
                "shelfW",
                {
                  "le": [
                    "freeWidthH",
                    1
                  ]
                }
              ]
            },
            {
              "and": [
                "shelfN",
                "shelfS",
                {
                  "le": [
                    "freeWidthV",
                    1
                  ]
                }
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "single_file_shelf_aisle"
        ]
      }
    },
    "justification": "The rule depends on local aisle geometry and shelf adjacency, so it applies to any layout with narrow shelf aisles rather than to named cells."
  },
  {
    "id": "park_cart_only_in_open_staging_area",
    "text": "If a shopper parks or releases a cart, they should do so only in an open staging area rather than beside shelves or in a constricted passage.",
    "abstraction": {
      "state_properties": {
        "open_staging_area": {
          "and": [
            {
              "not": "adjShelf"
