            {
              "ge": [
                "freeWidthH",
                5
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            }
          ]
        }
      },
      "events": {
        "cart_drop": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cart_drop",
          {
            "not": "open_staging_area"
          }
        ]
      }
    },
    "justification": "The notion of an open staging area is defined by local clearance and absence of adjacent shelves, not by a particular store coordinate."
  },
  {
    "id": "retrieve_parked_cart",
    "text": "After parking a cart, the shopper is obliged to retrieve a cart before leaving.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "cart_drop": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart"
            ]
