        "cart_pickup": {
          "pre": {
            "and": [
              "INTERACT",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cart_drop",
      "discharge": "cart_pickup"
    },
    "justification": "Retrieving a cart one has parked is a general shopping practice independent of where the parking place is located."
  },
  {
    "id": "enter_narrow_aisle_only_to_shop",
    "text": "When a shopper enters a single-file shelf aisle without a cart, they are obliged to perform the shelf interaction there before returning.",
    "abstraction": {
      "state_properties": {
        "single_file_shelf_aisle": {
          "or": [
            {
              "and": [
                "shelfE",
                "shelfW",
                {
                  "le": [
                    "freeWidthH",
                    1
                  ]
                }
              ]
            },
            {
              "and": [
                "shelfN",
                "shelfS",
                {
                  "le": [
                    "freeWidthV",
                    1
                  ]
                }
              ]
            }
          ]
        }
      },
      "events": {
        "enter_single_file_without_cart": {
          "pre": {
            "and": [
              "MOVE",
              {
                "not": "hasCart"
              },
              {
                "not": "single_file_shelf_aisle"
              }
            ]
          },
          "post": "single_file_shelf_aisle"
        },
        "shelf_service_in_single_file_without_cart": {
          "pre": {
            "and": [
              "INTERACT",
              {
                "not": "hasCart"
              },
              "single_file_shelf_aisle"
            ]
          },
          "post": null
