      "type": "obligation",
      "trigger": "enter_single_file_without_cart",
      "discharge": "shelf_service_in_single_file_without_cart"
    },
    "justification": "The rule refers to entering a locally identified narrow shelf aisle, so it generalizes across stores with different aisle positions."
  },
  {
