  },
  {
    "id": "limited_offcart_travel",
    "text": "When not holding a cart, a shopper may move only within open staging areas or single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "open_staging_area": {
          "and": [
            {
              "not": "adjShelf"
